import { FC, HTMLAttributes, ReactNode } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { Flex, Table, TableColumnsType } from 'antd';

import { getBrokenLink, useGetBrokenLinksListQuery } from 'entities/BrokenLink';
import { BrokenLinksFilters } from 'features/Filters';
import { Pagination } from 'features/Pagination';
import { EmptyState, OverlayLoader } from 'shared/ui';
import { getDefaultSortOrder, getTableSorter } from 'shared/utils';

interface DataType {
	key: React.Key;
	source: ReactNode;
	offer: ReactNode;
	brand: ReactNode;
	original_url: ReactNode;
	first_click_time: ReactNode;
	last_click_time: ReactNode;
	error_code: ReactNode;
	clicks_count: ReactNode;
}

interface IBrokenLinksListProps extends HTMLAttributes<HTMLDivElement> {}

export const BrokenLinksList: FC<IBrokenLinksListProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const [searchParams, setSearchParams] = useSearchParams();
	const { data, isFetching } = useGetBrokenLinksListQuery(searchParams.toString());
	const hasData = !!data?.results?.length;

	const columns: TableColumnsType<DataType> = [
		{
			dataIndex: 'source',
			key: 'source',
			title: t('Площадка'),
			defaultSortOrder: getDefaultSortOrder('name', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'offer',
			key: 'offer',
			title: t('Оффер'),
			defaultSortOrder: getDefaultSortOrder('status', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'brand',
			key: 'brand',
			title: t('Бренд'),
			defaultSortOrder: getDefaultSortOrder('brand', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'original_url',
			key: 'original_url',
			title: t('Трекинговая ссылка'),
		},
		{
			dataIndex: 'first_click_time',
			key: 'first_click_time',
			title: t('Дата поломки ссылки'),
			defaultSortOrder: getDefaultSortOrder('first_click_time', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'last_click_time',
			key: 'last_click_time',
			title: t('Дата последнего перехода'),
			defaultSortOrder: getDefaultSortOrder('last_click_time', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'error_code',
			key: 'error_code',
			title: t('Причина'),
			defaultSortOrder: getDefaultSortOrder('error_code', searchParams),
			sorter: true,
		},
		{
			dataIndex: 'clicks_count',
			key: 'clicks_count',
			title: t('Кол-во кликов по битой ссылке'),
			defaultSortOrder: getDefaultSortOrder('clicks_count', searchParams),
			sorter: true,
		},
	];

	const dataSource = hasData
		? data?.results?.map<DataType>((link, i) => {
				return getBrokenLink(link, i);
			})
		: [];

	return (
		<Flex vertical gap={20} {...props} className={className}>
			{isFetching && <OverlayLoader />}

			<BrokenLinksFilters />

			{!hasData && !isFetching && <EmptyState title={t('Битых ссылок не найдено')} />}

			{hasData && (
				<>
					<Table<DataType>
						columns={columns}
						dataSource={dataSource}
						bordered={false}
						scroll={{ x: 'max-content' }}
						pagination={false}
						showSorterTooltip={false}
						onChange={getTableSorter<DataType>(searchParams, setSearchParams)}
					/>

					<Pagination count={data?.count || 1} />
				</>
			)}
		</Flex>
	);
};
