import { FC, HTMLAttributes } from 'react';

import { useTrans } from 'shared/hooks';
import { EBrokenLinksErrors } from 'shared/typings';

interface IBrokenLinkErrorProps extends HTMLAttributes<HTMLDivElement> {
	errorCode: EBrokenLinksErrors;
}

export const BrokenLinkError: FC<IBrokenLinkErrorProps> = ({ errorCode }) => {
	const { brokenLinksErrors } = useTrans();
	return brokenLinksErrors[errorCode] || errorCode;
};
