import { FC } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, DatePicker, Drawer, DrawerProps, Flex, Form, Select } from 'antd';
import cn from 'classnames';

import { EFilters, useDateFilters, useFilters } from 'features/Filters';
import { useDisableBodyScroll, useTrans } from 'shared/hooks';
import { EBrokenLinksErrors } from 'shared/typings';

import styles from './BrokenLinksExtendedFilters.module.scss';

interface IBrokenLinksExtendedFiltersProps extends DrawerProps {}

export const BrokenLinksExtendedFilters: FC<IBrokenLinksExtendedFiltersProps> = ({
	className,
	onClose,
	open,
	...props
}) => {
	const { t } = useTranslation();
	const {
		sourcesOptions,
		brandsOptions,
		offersOptions,
		sourcesIsFetching,
		brandsIsFetching,
		offersIsFetching,
		onFilterChange,
		getALLFilterValues,
		clearFilters,
	} = useFilters();
	const dateFromKey = EFilters.LAST_CLICK_TIME_AFTER;
	const dateToKey = EFilters.LAST_CLICK_TIME_BEFORE;
	const { dateAfter, dateBefore, onDateChange } = useDateFilters(dateFromKey, dateToKey);
	const { brokenLinksErrors } = useTrans();

	useDisableBodyScroll(!!open);

	return (
		<Drawer
			{...props}
			open={open}
			onClose={onClose}
			width={450}
			title={t('Фильтры')}
			className={cn(className, styles.brandExtendedFilters)}>
			<Flex vertical gap={16}>
				<Form.Item label={t('Площадка')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.SOURCE_ID, value)}
						value={sourcesIsFetching ? null : getALLFilterValues(EFilters.SOURCE_ID)}
						options={sourcesOptions}
						loading={sourcesIsFetching}
						disabled={sourcesIsFetching}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать площадку')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Брэнд')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.BRAND_ID, value)}
						value={brandsIsFetching ? null : getALLFilterValues(EFilters.BRAND_ID)}
						options={brandsOptions}
						loading={brandsIsFetching}
						disabled={brandsIsFetching}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать брэнд')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Оффер')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.OFFER_ID, value)}
						value={offersIsFetching ? null : getALLFilterValues(EFilters.OFFER_ID)}
						options={offersOptions}
						loading={offersIsFetching}
						disabled={offersIsFetching}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать оффер')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Причина')} layout="vertical">
					<Select
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.ERROR_CODE, value)}
						value={getALLFilterValues(EFilters.ERROR_CODE)}
						options={Object.keys(brokenLinksErrors).map((code) => ({
							value: code,
							label: brokenLinksErrors[code as EBrokenLinksErrors],
						}))}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать причину')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Дата')} layout="vertical">
					<DatePicker.RangePicker
						width={'100%'}
						className={styles.date}
						format="DD.MM.YYYY"
						placeholder={[t('Дата с'), t('Дата по')]}
						value={[dateAfter, dateBefore]}
						style={{ minWidth: 230 }}
						onChange={(value) => {
							onDateChange(value?.[0] || null, dateFromKey, true, false);
							onDateChange(value?.[1] || null, dateToKey, true, true);
						}}
					/>
				</Form.Item>

				<Flex justify="space-between" className={styles.buttons}>
					<Button
						onClick={(e) => {
							clearFilters();
							onClose?.(e);
						}}>
						{t('Сбросить фильтры')}
					</Button>
					<Button type="primary" onClick={onClose}>
						{t('Применить')}
					</Button>
				</Flex>
			</Flex>
		</Drawer>
	);
};
