import { Typography } from 'antd';

import { BrokenLinkError, IBrokenLink } from 'entities/BrokenLink';
import { CopyLink } from 'shared/ui';
import { formatDate, formatNumber } from 'shared/utils';

export const getBrokenLink = (link: IBrokenLink, key: number) => {
	const { source, offer, brand, original_url, first_click_time, last_click_time, error_code, clicks_count } = link;

	return {
		key,
		source: source?.name || '-',
		offer: offer?.name || '-',
		brand: brand?.name || '-',
		original_url: <CopyLink url={original_url} maxWidth={200} textDecoration="none" />,
		first_click_time: (
			<>
				<div>{formatDate(new Date(first_click_time), 'short')}</div>
				<Typography.Text type="secondary">{formatDate(new Date(first_click_time), 'time')}</Typography.Text>
			</>
		),
		last_click_time: (
			<>
				<div>{formatDate(new Date(last_click_time), 'short')}</div>
				<Typography.Text type="secondary">{formatDate(new Date(last_click_time), 'time')}</Typography.Text>
			</>
		),
		error_code: <BrokenLinkError errorCode={error_code} />,
		clicks_count: formatNumber(clicks_count),
	};
};
