import { HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Badge, Button, DatePicker, Input } from 'antd';
import cn from 'classnames';

import FiltersIcon from 'assets/images/icons/filters.svg?react';
import { BrokenLinksExtendedFilters, EFilters, useDateFilters, useFilters } from 'features/Filters';

import styles from './BrokenLinksFilters.module.scss';

export interface IBrokenLinksFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const BrokenLinksFilters = ({ className, ...props }: IBrokenLinksFiltersProps) => {
	const { t } = useTranslation();
	const [filtersIsOpened, setFiltersIsOpened] = useState(false);
	const { getFiltersCount, onFilterChange, getFilterValue } = useFilters();
	const dateFromKey = EFilters.LAST_CLICK_TIME_AFTER;
	const dateToKey = EFilters.LAST_CLICK_TIME_BEFORE;
	const { dateAfter, dateBefore, onDateChange } = useDateFilters(dateFromKey, dateToKey);

	return (
		<div {...props} className={cn(className, styles.filters)}>
			<Input
				placeholder={t('Поиск по ссылке')}
				value={getFilterValue(EFilters.SEARCH_ID) || ''}
				onChange={(e) => onFilterChange(EFilters.SEARCH_ID, e.target.value)}
				allowClear
				style={{ maxHeight: 40 }}
			/>

			<DatePicker.RangePicker
				format="DD.MM.YYYY"
				placeholder={[t('Дата с'), t('Дата по')]}
				value={[dateAfter, dateBefore]}
				style={{ minWidth: 230 }}
				onChange={(value) => {
					onDateChange(value?.[0] || null, dateFromKey, true, false);
					onDateChange(value?.[1] || null, dateToKey, true, true);
				}}
			/>

			<Button icon={<FiltersIcon />} onClick={() => setFiltersIsOpened(true)}>
				{t('Фильтры')} <Badge size="small" count={getFiltersCount()} />
			</Button>

			<BrokenLinksExtendedFilters open={filtersIsOpened} onClose={() => setFiltersIsOpened(false)} />
		</div>
	);
};

export default BrokenLinksFilters;
