import { TBrokenLinksList } from 'entities/BrokenLink';
import { commonApi } from 'shared/api/commonApi';

export const brokenLinksApi = commonApi.injectEndpoints({
	endpoints: (builder) => ({
		getBrokenLinksList: builder.query<TBrokenLinksList, string>({
			query: (params) => ({
				url: `reports/broken_links/${params ? '?' : ''}${params}`,
			}),
		}),
	}),
	overrideExisting: false,
});

export const { useGetBrokenLinksListQuery } = brokenLinksApi;
